func (cfg Config) validate() error {
	if len(cfg.OperatorForward) != 0 {
		if _, _, err := operatorForwarding(cfg); err != nil {
			return err
		}
	}
	if !cellName.MatchString(cfg.Cell) || !cellName.MatchString(cfg.Instance) {
		return errors.New("cell and instance must be lowercase NATS tokens")
	}
	// Every protocol subject builder refuses the reserved scope as a cell
	// and returns "", which would surface far from here as empty grants.
	if cfg.Cell == protocol.GlobalScope {
		return errors.New("cell name is reserved for the global scope")
	}
	if cfg.Replicas != 1 && cfg.Replicas != 3 && cfg.Replicas != 5 {
		return errors.New("regional replicas must be 1, 3, or 5")
	}
	if cfg.ClientRole != "" && cfg.ClientRole != "controller" && cfg.ClientRole != "operator" && cfg.ClientRole != "host" {
		return errors.New("invalid regional NATS client role")
	}
	if cfg.Embedded == nil && cfg.URL == "" {
		return errors.New("regional NATS URL or embedded server is required")
	}
	if cfg.NKeySeedFile != "" && cfg.CredentialsFile != "" {
		return errors.New("choose one regional NKey seed or JWT credentials file")
	}
	if !cfg.TLS.complete() || cfg.CredentialsFile == "" || cfg.NKeySeedFile != "" {
		return errors.New("regional NATS requires client TLS and JWT credentials")
	}
	if cfg.Embedded != nil && (!cfg.Embedded.TLS.complete() || !cfg.Embedded.RouteTLS.complete() ||
		cfg.Embedded.OperatorJWTFile == "" || cfg.Embedded.SystemJWTFile == "" ||
		cfg.Embedded.CellJWTFile == "" || cfg.Embedded.SystemCredentialsFile == "" ||
		cfg.Embedded.TicketPublicKeyFile == "" || len(cfg.Embedded.BrokerIDs) != cfg.Replicas || len(cfg.Embedded.Users) != 0) {
		return errors.New("production embedded NATS requires operator/system/cell JWTs, system credentials, and client/route TLS")
	}
	if cfg.Embedded != nil {
		e := cfg.Embedded
		if e.InterRegion != nil && e.Link != nil {
			return errors.New("a region links to peers by interregion or by link, not both")
		}
		if err := e.InterRegion.validate(cfg); err != nil {
			return err
		}
		if e.Link != nil {
			if err := e.Link.validate(cfg); err != nil {
				return err
			}
		}
		seen := make(map[string]struct{}, len(e.BrokerIDs))
		for _, id := range e.BrokerIDs {
			if !cellName.MatchString(id) {
				return errors.New("production broker ID is invalid")
			}
			if _, exists := seen[id]; exists {
				return errors.New("production broker IDs must be unique")
			}
			seen[id] = struct{}{}
		}
		if _, own := seen[cfg.Instance]; !own {
			return errors.New("production broker ID list excludes this instance")
		}
		if e.StoreDir == "" || e.Host == "" || e.Port == 0 {
			return errors.New("embedded NATS requires store_dir, host, and port")
		}
		if e.StoreMaxBytes < 0 {
			return errors.New("embedded NATS store_max_bytes must be positive when set")
		}
		if cfg.Replicas > 1 && (e.RouteHost == "" || e.RoutePort == 0 || len(e.Routes) == 0) {
			return errors.New("clustered NATS requires route_host, route_port and at least one seed route")
		}
		if cfg.Replicas > 1 && (e.RouteUser == "" || e.RoutePasswordFile == "") {
			return errors.New("production NATS routes require a route user and password file")
		}
	}
	return nil
}

func (f TLSFiles) complete() bool {
	return f.CAFile != "" && f.CertFile != "" && f.KeyFile != ""
}

func validCell(cell string) bool {
	if !nameRE.MatchString(cell) || cell == protocol.GlobalScope {
		return false
	}
	_, err := protocol.CanonicalRegion(cell)
	return err == nil
}

func CanonicalRegion(region string) (string, error) {
	if region == "" || len(region) > 63 {
		return "", fmt.Errorf("%w: region length is out of bounds", ErrInvalidSubjectToken)
	}
	region = strings.ToUpper(region)
	if region == "GLOBAL" {
		return region, nil
	}
	previousHyphen := true
	for _, character := range region {
		if character == '-' {
			if previousHyphen {
				return "", ErrInvalidSubjectToken
			}
			previousHyphen = true
			continue
		}
		if character < 'A' || character > 'Z' {
			if character < '0' || character > '9' {
				return "", ErrInvalidSubjectToken
			}
		}
		previousHyphen = false
	}
	if previousHyphen {
		return "", ErrInvalidSubjectToken
	}
	return region, nil
}

func (c *plannerRefusalCounter) note(key string) int {
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.counts == nil {
		c.counts = map[string]int{}
	}
	if _, tracked := c.counts[key]; !tracked {
		for len(c.counts) >= maxTrackedPlannerRefusals && len(c.order) > 0 {
			oldest := c.order[0]
			c.order = c.order[1:]
			delete(c.counts, oldest)
		}
		c.order = append(c.order, key)
	}
	c.counts[key]++
	return c.counts[key]
}

func (c *plannerRefusalCounter) forget(key string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if _, tracked := c.counts[key]; !tracked {
		return
	}
	delete(c.counts, key)
	if index := slices.Index(c.order, key); index >= 0 {
		c.order = slices.Delete(c.order, index, index+1)
	}
}

func (shapedPlanner) Plan(context.Context, Intent) ([]host.Desired, error) {
	panic("a shaped planner must be asked for its shape")
}

func (p shapedPlanner) PlanShaped(_ context.Context, i Intent) (PlanShape, []host.Desired, error) {
	var plan []host.Desired
	for _, node := range []string{"node-a", "node-b", "node-c"}[:p.shape.Replicas] {
		plan = append(plan, host.Desired{Cell: i.Cell, Node: node, Environment: i.Environment, Role: i.Role,
			Digest: i.ArtifactDigest, Generation: p.shape.Generation, AuthorityEpoch: i.AuthorityEpoch})
	}
	return p.shape, plan, nil
}

func (s *Service) plan(ctx context.Context, intent Intent) (PlanShape, []host.Desired, error) {
	if shaped, ok := s.config.Planner.(ShapedPlanner); ok {
		return shaped.PlanShaped(ctx, intent)
	}
	plan, err := s.config.Planner.Plan(ctx, intent)
	return defaultPlanShape(intent), plan, err
}

func defaultPlanShape(intent Intent) PlanShape {
	return PlanShape{Generation: intent.Generation, Replicas: intent.DesiredReplicas}
}

func (op operation) planShape() PlanShape {
	if op.Shape != nil {
		return *op.Shape
	}
	return defaultPlanShape(op.Intent)
}

func validatePlan(intent Intent, shape PlanShape, plan []host.Desired) error {
	// A shaped release may only move the desired generation forward and must
	// stay within the autoscaler's replica bound (ReleaseShape already clamps
	// it to the signed spec bounds; it need not equal the intent's count).
	if shape.Generation < intent.Generation || shape.Replicas < 0 || shape.Replicas > maxReplicas {
		return ErrInvalid
	}
	seen := make(map[string]struct{}, len(plan))
	active := 0
	for _, d := range plan {
		if d.Cell != intent.Cell || d.Role != intent.Role || d.Environment != intent.Environment || d.Generation != shape.Generation || d.AuthorityEpoch != intent.AuthorityEpoch || !nameRE.MatchString(d.Node) {
			return ErrInvalid
		}
		if _, ok := seen[d.Node]; ok {
			return ErrInvalid
		}
		seen[d.Node] = struct{}{}
		if d.Withdrawn {
			if d.Digest != "" || len(d.Args) != 0 || len(d.Env) != 0 || len(d.Secrets) != 0 {
				return ErrInvalid
			}
			continue
		}
		if d.Digest != intent.ArtifactDigest || ConfigDigestOf(d.Args, d.Env, d.Secrets) != intent.ConfigDigest {
			return ErrInvalid
		}
		active++
	}
	if active != shape.Replicas || !slices.IsSortedFunc(plan, func(a, b host.Desired) int {
		if a.Node < b.Node {
			return -1
		}
		if a.Node > b.Node {
			return 1
		}
		return 0
	}) {
		return ErrInvalid
	}
	return nil
}
